const tabId = 2017691689;

async function getPageJobs() {
  return await browserjs(tabId, () => {
    // In Shazamme, let's see how each job card is structured
    const cards = Array.from(document.querySelectorAll('[data-rel="job-card"], .shm-job-card, [class*="job-results-item"], .dmRespRow[data-rel]'));
    // If not found, look for titles
    const links = Array.from(document.querySelectorAll('a[href*="/job-details/"]'));
    return links.map(a => {
      // Find containing block
      let p = a.parentElement;
      for (let i = 0; i < 5 && p; i++) {
        if (p.innerText.includes('APPLY NOW') || p.innerText.includes('Posted')) break;
        p = p.parentElement;
      }
      return {
        title: a.innerText.trim(),
        href: a.href,
        snippet: p ? p.innerText.replace(/\n+/g, ' | ') : ''
      };
    }).filter(j => j.title.length > 0 && j.title !== 'READ MORE');
  });
}

const allJobs = [];
for (let page = 0; page < 6; page++) {
  console.log(`Getting page ${page + 1}...`);
  if (page > 0) {
    await browserjs(tabId, (pageNum) => {
      const btn = document.querySelector(`.section-job-results-paging a[data-page-number="${pageNum}"]`);
      if (btn) btn.click();
    }, page);
    await new Promise(r => setTimeout(r, 1500));
  }
  const jobs = await getPageJobs();
  for (const j of jobs) {
    if (!allJobs.some(x => x.href === j.href)) {
      allJobs.push(j);
    }
  }
}

console.log(`Total Legal People jobs scraped: ${allJobs.length}`);
console.log(JSON.stringify(allJobs.slice(0, 10), null, 2));
await write("tmp://legal_people_jobs.json", JSON.stringify(allJobs, null, 2));

