const tabId = 2017691756;

const queries = [
  'keywords="New Zealand" lawyer',
  'keywords="NZ admitted"',
  'keywords="New Zealand admitted"',
  'keywords="Trans-Tasman"',
  'keywords="commonwealth" lawyer',
  'keywords="2-4 PQE" lawyer',
  'keywords="2-4 years" lawyer',
  'keywords="3 PQE" lawyer'
];

const foundJobs = [];

for (const q of queries) {
  const url = `https://au.seek.com/jobs-in-legal?${encodeURI(q)}`;
  console.log("Searching:", url);
  await tool.navigate({ tabId, url });
  await tool.wait_for({ tabId, condition: "load_state", value: "load" });
  await new Promise(r => setTimeout(r, 1500));

  const jobs = await browserjs(tabId, () => {
    const cards = Array.from(document.querySelectorAll('article[data-card-type="JobCard"]'));
    return cards.map(c => {
      const titleLink = c.querySelector('a[data-automation="jobTitle"]');
      const company = c.querySelector('a[data-automation="jobCompany"]')?.innerText || c.querySelector('[data-automation="jobCompany"]')?.innerText;
      const location = c.querySelector('a[data-automation="jobLocation"]')?.innerText || c.querySelector('[data-automation="jobLocation"]')?.innerText;
      const subClass = c.querySelector('[data-automation="jobSubClassification"]')?.innerText;
      const snippet = c.querySelector('[data-automation="jobShortDescription"]')?.innerText;
      return {
        title: titleLink?.innerText,
        href: titleLink?.href,
        company,
        location,
        subClass,
        snippet
      };
    }).filter(j => j.title && j.href);
  });
  console.log(`Found ${jobs.length} jobs for query ${q}`);
  for (const j of jobs) {
    if (!foundJobs.some(x => x.href === j.href)) {
      foundJobs.push({ ...j, query: q });
    }
  }
