  const data = await browserjs(tabId, () => {
    const text = document.body.innerText;
    const aboutYouIdx = text.indexOf("About you");
    const snippet = aboutYouIdx !== -1 ? text.slice(aboutYouIdx, aboutYouIdx + 1000) : text.slice(2000, 3000);
    // Location
    const locMatch = text.match(/(Sydney|Melbourne|Perth|Brisbane)/i);
    return {
      title: document.querySelector('h1, h2, .role-title')?.innerText || document.title,
      loc: locMatch ? locMatch[0] : "Not shown",
      snippet
    };
  });
  gtResults.push({ ...ad, url, data });
}

console.log("GT details:", JSON.stringify(gtResults, null, 2));

