const tabId = 2017691756;

const joraJobs = [];

for (let page = 1; page <= 5; page++) {
  const url = `https://au.jora.com/j?q=lawyer+New+Zealand&l=Australia&p=${page}`;
  console.log(`Navigating to Jora page ${page}: ${url}`);
  await tool.navigate({ tabId, url });
  await tool.wait_for({ tabId, condition: "load_state", value: "load" });
  await new Promise(r => setTimeout(r, 1200));

  const jobs = await browserjs(tabId, () => {
    // Look for all job cards / links on Jora
    const links = Array.from(document.querySelectorAll('a[href*="/job/"]'));
    return links.map(a => {
      const card = a.closest('.job-card, [data-testid="job-card"], article, li, div') || a;
      return {
        title: a.innerText.trim(),
        href: a.href,
        text: card.innerText.replace(/\n+/g, ' | ').slice(0, 300)
      };
    }).filter(j => j.title.length > 3 && !j.title.includes('Apply'));
  });
  console.log(`Page ${page} found ${jobs.length} jobs`);
  for (const j of jobs) {
    if (!joraJobs.some(x => x.href === j.href)) {
      joraJobs.push(j);
    }
  }
}

console.log(`Total unique Jora jobs: ${joraJobs.length}`);
console.log(JSON.stringify(joraJobs.slice(0, 15), null, 2));
await write("tmp://jora_nz_jobs.json", JSON.stringify(joraJobs, null, 2));

