const tabId = 2017691756;
const montJobs = await browserjs(tabId, () => {
  const items = Array.from(document.querySelectorAll('.job-item, .job-listing, .job, [class*="job"]'));
  // Look for headings and "Read More"
  const readMoreLinks = Array.from(document.querySelectorAll('a')).filter(a => a.innerText.trim() === 'Read More' || a.innerText.trim() === 'Apply Now');
  return readMoreLinks.map(a => {
    let p = a.parentElement;
    for (let i = 0; i < 5 && p; i++) {
      if (p.innerText.includes('Job Id:') || p.innerText.includes('Date Posted:')) break;
      p = p.parentElement;
    }
    return {
      text: a.innerText.trim(),
      href: a.href,
      snippet: p ? p.innerText.replace(/\n+/g, ' | ') : ''
    };
  });
});
console.log("Montgomery jobs count:", montJobs.length);
console.log(montJobs.slice(0, 10));

