const tabId = 2017691756;

// Let's inspect single jobs on Montgomery Advisory to see their details
const montJobIds = [
  "4463427", // Lawyer or SA - Employment (Brisbane)
  "4463444", // Front-End Construction Lawyer (Brisbane)
  "4463478", // Lawyer - Commercial & Projects (Sydney)
  "4463480"  // Lawyer or SA - Energy, Resources (Melbourne)
];

const montDetails = [];
for (const id of montJobIds) {
  const url = `https://www.montgomeryadvisory.com.au/single-job/?ads=${id}`;
  await tool.navigate({ tabId, url });
  await tool.wait_for({ tabId, condition: "load_state", value: "load" });
  const data = await browserjs(tabId, () => {
    return {
      title: document.querySelector('h1, h2')?.innerText,
      body: document.body.innerText
    };
  });
  montDetails.push({ id, url, data });
}

console.log("Montgomery inspected count:", montDetails.length);
for (const m of montDetails) {
  console.log("=== ID:", m.id, "Title:", m.data.title);
  console.log("Snippet:", m.data.body.slice(0, 800));
}
await write("tmp://mont_inspected.json", JSON.stringify(montDetails, null, 2));

