const tabId = 2017691756;
const joraUrls = [
  "https://au.jora.com/job/Lawyer-35fec476372d493ec3c79d9721406ac4?abstract_type=extended_llm",
  "https://au.jora.com/job/Legal-Counsel-34f1d5f291c121d5b5ef9b811a27b66a?abstract_type=extended_llm",
  "https://au.jora.com/job/Corporate-Counsel-5f89d4b55c8a1928d9d3e68a9f3a4f38?abstract_type=extended_llm",
  "https://au.jora.com/job/Legal-Counsel-c9bb18871fed7aef2f882c530476f0bf?abstract_type=extended_llm"
];

const results = [];
for (const url of joraUrls) {
  await tool.navigate({ tabId, url });
  await tool.wait_for({ tabId, condition: "load_state", value: "load" });
  const data = await browserjs(tabId, () => {
    return {
      title: document.querySelector('h1, h2')?.innerText || document.title,
      body: document.body.innerText
    };
  });
  results.push({ url, data });
}

for (const r of results) {
  console.log("=== Title:", r.data.title);
  // find lines mentioning requirements, qualifications, admission, etc.
  const lines = r.data.body.split('\n').filter(l => l.trim().length > 0);
  const reqLines = lines.filter(l => /admission|admitted|practising|practicing|qualification|degree|pae|pqe|experience|australia|zealand/i.test(l));
  console.log("Requirements lines:", reqLines.slice(0, 8));
}
await write("tmp://jora_inspected_batch1.json", JSON.stringify(results, null, 2));

