const tabId = 2017691756;
const searchUrls = [
  "https://au.jora.com/j?q=lawyer+2..4+PQE+Perth&l=Perth+WA",
  "https://au.jora.com/j?q=lawyer+2..4+PQE+Canberra&l=Canberra+ACT",
  "https://au.jora.com/j?q=lawyer+2..4+PQE+Brisbane&l=Brisbane+QLD"
];

const found = [];
for (const u of searchUrls) {
  await tool.navigate({ tabId, url: u });
  await tool.wait_for({ tabId, condition: "load_state", value: "load" });
  await new Promise(r => setTimeout(r, 1200));

  const jobs = await browserjs(tabId, () => {
    const cards = Array.from(document.querySelectorAll('a[href*="/job/"]'));
    return cards.map(a => {
      const card = a.closest('.job-card, [data-testid="job-card"], article, li, div') || a;
      return {
        title: a.innerText.trim(),
        href: a.href,
        text: card.innerText.replace(/\n+/g, ' | ').slice(0, 300)
      };
    }).filter(j => j.title.length > 3 && !j.title.includes('Apply'));
  });
  console.log(`URL ${u} found ${jobs.length} jobs`);
  found.push(...jobs);
}

console.log("Total found:", found.length);
console.log(found.slice(0, 10));
await write("tmp://jora_regional_jobs.json", JSON.stringify(found, null, 2));

