const { text } = await read("tmp://shortlist_20_roles.json");
const roles = JSON.parse(text);

const headers = [
  "Role #",
  "Eligibility Bucket",
  "Job Title",
  "Employer / Recruiter",
  "City / State",
  "Practice Area",
  "Stated PQE / Experience Range",
  "NZ-Qualified / Admitted Mentioned?",
  "Australian Admission Mandatory?",
  "Practising Cert / Relocation Mentioned?",
  "Application Link",
  "Strategic Assessment / Notes"
];

const tsvRows = [headers.join("\t")];

for (const r of roles) {
  const row = [
    r.id,
    r.bucket,
    r.title,
    r.employerOrRecruiter,
    r.cityState,
    r.practiceArea,
    r.pqe,
    r.nzMentioned,
    r.ausAdmissionMandatory,
    r.practisingOrRelocation,
    r.url,
    r.notes
  ];
  // Sanitize tabs or newlines
  const sanitized = row.map(v => String(v || "Not shown").replace(/\t/g, " ").replace(/\r?\n/g, " "));
  tsvRows.push(sanitized.join("\t"));
}

const tsv = tsvRows.join("\n");
await write("tmp://tracker.tsv", tsv);
console.log(`TSV generated: ${tsvRows.length} rows, ${tsv.length} characters.`);
console.log("Sample TSV header & row 1:\n", tsvRows[0], "\n", tsvRows[1]);

